<?php
require_once __DIR__.'/includes/functions.php';must_login();require_permission('attentions');if($_SESSION['user']['rol']==='Especialista'&&empty($_SESSION['user']['especialista_id'])){http_response_code(403);exit('Tu usuario no tiene un perfil de especialista vinculado.');}check_csrf();require_once __DIR__.'/config/database.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try{$cita=(int)$_POST['cita_id'];$desc=trim($_POST['descripcion']??'');$obs=trim($_POST['observaciones']??'');$items=$_POST['producto']??[];$cant=$_POST['cantidad']??[];$pdo->beginTransaction();$q=$pdo->prepare('SELECT id FROM citas WHERE id=? AND (especialista_id=? OR ?=0) AND estado IN ("Confirmada","Pendiente","En atención") FOR UPDATE');$specialistId=$_SESSION['user']['rol']==='Especialista'?(int)$_SESSION['user']['especialista_id']:0;$q->execute([$cita,$specialistId,$specialistId]);if(!$q->fetch())throw new RuntimeException('La cita no está disponible para registrar atención.');$pdo->prepare('INSERT INTO atenciones(cita_id,descripcion,observaciones) VALUES(?,?,?)')->execute([$cita,$desc,$obs]);$aid=(int)$pdo->lastInsertId();foreach($items as $i=>$pid){$pid=(int)$pid;$qty=(float)($cant[$i]??0);if(!$pid||$qty<=0)continue;$st=$pdo->prepare('SELECT stock FROM productos WHERE id=? FOR UPDATE');$st->execute([$pid]);$stock=$st->fetchColumn();if($stock===false||$stock<$qty)throw new RuntimeException('Stock insuficiente para uno de los productos.');$pdo->prepare('INSERT INTO atencion_productos(atencion_id,producto_id,cantidad) VALUES(?,?,?)')->execute([$aid,$pid,$qty]);$pdo->prepare('UPDATE productos SET stock=stock-? WHERE id=?')->execute([$qty,$pid]);$pdo->prepare('INSERT INTO movimientos_inventario(producto_id,tipo,cantidad,motivo) VALUES(?,"Salida",?,?)')->execute([$pid,$qty,'Consumo en atención #'.$aid]);}$pdo->prepare('UPDATE citas SET estado="Atendida" WHERE id=?')->execute([$cita]);$pdo->commit();flash('Atención registrada y productos descontados del inventario.');go('atenciones.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException?'No se pudo registrar la atención.':$e->getMessage();}
$sqlCitas='SELECT c.id,c.fecha,c.hora_inicio,CONCAT(cl.nombres," ",cl.apellidos) cliente,s.nombre servicio FROM citas c JOIN clientes cl ON cl.id=c.cliente_id JOIN servicios s ON s.id=c.servicio_id LEFT JOIN atenciones a ON a.cita_id=c.id WHERE a.id IS NULL AND c.estado IN ("Pendiente","Confirmada","En atención")';if($_SESSION['user']['rol']==='Especialista')$sqlCitas.=' AND c.especialista_id='.(int)$_SESSION['user']['especialista_id'];$sqlCitas.=' ORDER BY c.fecha,c.hora_inicio';$citas=$pdo->query($sqlCitas)->fetchAll();$productos=$pdo->query('SELECT id,nombre,stock,unidad FROM productos WHERE estado="Activo" AND stock>0 ORDER BY nombre')->fetchAll();$sqlRows='SELECT a.*,c.fecha,CONCAT(cl.nombres," ",cl.apellidos) cliente,s.nombre servicio FROM atenciones a JOIN citas c ON c.id=a.cita_id JOIN clientes cl ON cl.id=c.cliente_id JOIN servicios s ON s.id=c.servicio_id';if($_SESSION['user']['rol']==='Especialista')$sqlRows.=' WHERE c.especialista_id='.(int)$_SESSION['user']['especialista_id'];$sqlRows.=' ORDER BY a.id DESC LIMIT 100';$rows=$pdo->query($sqlRows)->fetchAll();$title='Registro de atenciones';require __DIR__.'/includes/header.php';?>
<div class="heading"><div><span class="eyebrow">SERVICIO AL CLIENTE</span><h1>Registro de atenciones</h1><p class="muted">Registra el procedimiento realizado y los productos consumidos.</p></div></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<div class="split"><section class="panel form-panel"><h2>Nueva atención</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label class="field"><span>Cita pendiente</span><select name="cita_id" required><option value="">Seleccionar cita</option><?php foreach($citas as $c):?><option value="<?=$c['id']?>"><?=e('#'.$c['id'].' · '.$c['fecha'].' '.$c['hora_inicio'].' · '.$c['cliente'].' — '.$c['servicio'])?></option><?php endforeach;?></select></label><label class="field"><span>Descripción de la atención</span><textarea name="descripcion" rows="3"></textarea></label><label class="field"><span>Observaciones</span><textarea name="observaciones" rows="2"></textarea></label><h3>Productos utilizados</h3><div id="product-rows"><div class="product-row"><select name="producto[]"><option value="">Sin producto</option><?php foreach($productos as $p):?><option value="<?=$p['id']?>"><?=e($p['nombre'].' · stock '.$p['stock'].' '.$p['unidad'])?></option><?php endforeach;?></select><input type="number" name="cantidad[]" min="0" step="0.01" placeholder="Cantidad"></div></div><button type="button" class="btn ghost" onclick="addProductRow()">+ Agregar producto</button><div class="actions"><button class="btn">Guardar atención</button></div></form></section><section class="panel table-panel"><h2>Atenciones recientes</h2><div class="tablewrap"><table><tr><th>Fecha</th><th>Cliente</th><th>Servicio</th><th>Descripción</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['fecha'])?></td><td><?=e($r['cliente'])?></td><td><?=e($r['servicio'])?></td><td><?=e($r['descripcion'])?></td></tr><?php endforeach;?></table></div></section></div><script>function addProductRow(){const el=document.querySelector('.product-row').cloneNode(true);el.querySelectorAll('select,input').forEach(x=>x.value='');document.getElementById('product-rows').appendChild(el)}</script><?php require __DIR__.'/includes/footer.php';?>
